(() => {
 const icon=(name)=>{const paths={search:'<circle cx="10.5" cy="10.5" r="6.5"/><path d="m16 16 5 5"/>',document:'<path d="M14 3H5v18h14V8Zm0 0v5h5M8 12h8m-8 4h6"/>',arrow:'<path d="M5 12h14m-6-6 6 6-6 6"/>',download:'<path d="M12 3v12m-4-4 4 4 4-4M4 16v5h16v-5"/>',filter:'<path d="M4 7h16M4 17h16"/><circle cx="9" cy="7" r="3"/><circle cx="15" cy="17" r="3"/>',chevron:'<path d="m7 10 5 5 5-5"/>',close:'<path d="m6 6 12 12M6 18 18 6"/>',back:'<path d="M19 12H5m6-6-6 6 6 6"/>',car:'<path d="m4 10 2-6h12l2 6M3 10h18v8H3Zm2 8v3m14-3v3M6 14h2m8 0h2"/>',check:'<path d="m5 12 4 4L19 6"/>'};return `<svg viewBox="0 0 24 24" aria-hidden="true">${paths[name]||paths.arrow}</svg>`;};
 const e=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const money=n=>new Intl.NumberFormat('en-IE',{style:'currency',currency:'EUR',maximumFractionDigits:0}).format(n);
 const button=(label,url,style='primary',ic='arrow',extra='')=>`<a class="button ${style} vl-button" href="${e(url)}" ${extra}>${label}<span class="action-icon">${icon(ic)}</span></a>`;
 const collectionStates=new Map();let lastLibraryRoute='prices';
 let dataPromise,state={brand:'all',query:'',engines:[],bodies:[],budget:0,sort:'range'},limit=24,core;
 function load(){return dataPromise||(dataPromise=Promise.all([fetch('data/vehicle-library.json').then(r=>{if(!r.ok)throw Error('Catalogue unavailable');return r.json()}),import('./vehicle-library-core.mjs')]).then(([data,module])=>{core=module;return data}).catch(err=>{dataPromise=null;throw err}));}
 const loading='<div class="vl-loading" role="status"><span></span>Loading models and published prices…</div>';
 window.renderUniPrices=(options={})=>{
  const brand=(window.uniCarsBrands||[]).find(b=>b.name===options.brand),route=options.route||'prices';
  const title=brand?e(brand.name)+' models.':options.title?e(options.title):'Your next car. <span>All the details.</span>';
  const description=brand?'Explore '+brand.name+' models, compare published starting prices and narrow your choice.':options.description||'Explore the range, compare starting prices and keep the price list that matters to you.';
  queueMicrotask(()=>mount());
  return `<section class="vehicle-library ${brand?'vl-collection':''}" id="vehicleLibrary" data-collection-brand="${e(brand?.name||'')}" data-library-route="${e(route)}"><div class="vl-wrap"><div class="vl-breadcrumb"><span>${e(brand?'Explore vehicles / Our brands / '+brand.name:options.breadcrumb||'Explore vehicles / Price lists & brochures')}</span>${brand?button('All brands','#brands','secondary','car'):''}</div><header class="vl-heading"><div><p class="vl-eyebrow">${brand?e(brand.name)+' collection':'THE UNICARS MODEL LIBRARY'}</p><h1>${title}</h1><p>${e(description)}</p></div><div class="vl-library-mark">${brand?`<img src="assets/brands/${brand.logo}.svg" alt="${e(brand.name)}" width="110" height="76">`:`${icon('document')}<span>Prices. Specifications.<br><strong>One clear place.</strong></span>`}</div></header><div id="vlContent">${loading}</div></div></section>`;
 };
 window.renderUniRangeVehicle=id=>{queueMicrotask(()=>mountVehicle(id));return `<section class="vehicle-library vl-detail-page" id="rangeVehicle"><div class="vl-wrap">${loading}</div></section>`;};
 function fail(root){root.innerHTML=`<div class="vl-empty"><h2>The model library couldn’t load.</h2><p>Please reload this page, or use the original Unicars price-list page.</p>${button('Open published price lists','https://www.unicars.com/gr/pricelists.php','primary','document','target="_blank" rel="noopener"')}</div>`;}
 async function mount(){const root=document.getElementById('vehicleLibrary');if(!root)return;try{const data=await load();if(!root.isConnected)return;const saved=collectionStates.get(root.dataset.libraryRoute);state=saved?.state||{...core.defaultFilters,engines:[],bodies:[],brand:root.dataset.collectionBrand||'all'};limit=saved?.limit||24;root.querySelector('#vlContent').innerHTML=layout(data,root.dataset.collectionBrand||null);bind(root,data);update(root,data);}catch(err){if(root.isConnected)fail(root.querySelector('#vlContent'));}}
 function optionList(name,options,selected){return options.map(([value,label])=>`<label class="vl-check"><input type="checkbox" name="${name}" value="${e(value)}" ${selected.includes(value)?'checked':''}><span class="vl-check-box">${icon('check')}</span><span>${e(label)}</span></label>`).join('');}
 function layout(data,collection=null){
 const scoped=core.collectionModels(data.models,collection);
 const brands=['Volkswagen','Audi','Škoda','CUPRA','SEAT'];const bodies=['Hatchback','SUV','Saloon','Estate','Convertible','MPV','Van','Pick-up'];
 const brandNavigation=collection?`<nav class="vl-brand-bar" aria-label="Brand collections"><a href="#brands">All brands</a>${window.uniCarsBrands.map(b=>`<a href="#${b.route}" ${b.name===collection?'aria-current="page"':''}><img src="assets/brands/${b.logo}.svg" alt="" width="24" height="22">${b.name}<span>${data.models.filter(m=>m.brand===b.name).length}</span></a>`).join('')}</nav>`:null;
 return `${brandNavigation||`<div class="vl-brand-bar" role="group" aria-label="Filter by brand"><button type="button" data-vl-brand="all" aria-pressed="${state.brand==='all'}">All brands <span>${data.models.length}</span></button>${brands.map(b=>`<button type="button" data-vl-brand="${b}" aria-pressed="${state.brand===b}">${b}<span>${data.models.filter(m=>m.brand===b).length}</span></button>`).join('')}</div>`}
 <div class="vl-workspace"><aside class="vl-filters"><button type="button" class="vl-mobile-filter" aria-expanded="false" aria-controls="vlFilterPanel">${icon('filter')}<span>Filters</span><span id="vlFilterBadge"></span>${icon('chevron')}</button><div class="vl-filter-panel" id="vlFilterPanel"><div class="vl-filter-title"><h2>Refine your choice</h2><button type="button" class="vl-reset" data-vl-reset>Reset all ${icon('close')}</button></div><form id="vlFilters"><fieldset><legend>Available engines</legend><p class="vl-field-help">Find models offering these engines.</p>${optionList('engine',Object.entries(core.engineNames).filter(([key])=>!collection||scoped.some(m=>m.powertrains.includes(key))),state.engines)}</fieldset><fieldset><legend>Body style</legend>${optionList('body',bodies.filter(b=>!collection||scoped.some(m=>m.body===b)).map(b=>[b,b]),state.bodies)}</fieldset><fieldset><legend>Model starting price</legend><p class="vl-field-help">With engine or body filters, the budget applies to matching versions.</p><div class="vl-budget-options">${[[0,'Any price'],[25000,'Up to €25,000'],[35000,'Up to €35,000'],[50000,'Up to €50,000'],[75000,'Up to €75,000']].map(([val,label])=>`<label class="vl-budget"><input type="radio" name="budget" value="${val}" ${state.budget===val?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset></form><button type="button" class="button primary vl-show-results">Show results ${icon('check')}</button></div></aside>
 <div class="vl-results"><div class="vl-toolbar"><label class="vl-search">${icon('search')}<span class="vl-sr-only">Search by brand or model</span><input id="vlSearch" type="search" placeholder="${collection?'Search '+e(collection)+' models':'Search a brand or model'}" value="${e(state.query)}" autocomplete="off"></label><details class="vl-sort"><summary><span><small>Sort by</small><strong id="vlSortLabel">Model range</strong></span>${icon('chevron')}</summary><div class="vl-sort-options" role="group" aria-label="Sort models">${[['range','Model range'],['price-low','Price: low to high'],['price-high','Price: high to low'],['name','Brand & model: A–Z']].map(([val,label])=>`<label><input type="radio" name="sort" value="${val}" ${state.sort===val?'checked':''}><span>${label}</span>${icon('check')}</label>`).join('')}</div></details></div>
 <div class="vl-results-meta"><p id="vlCount" role="status" aria-live="polite" aria-atomic="true"></p><span>Published prices · availability to confirm</span></div><div id="vlChips" class="vl-chips"></div><div class="vl-grid" id="vlGrid"></div><div class="vl-more" id="vlMore"></div></div></div>
 ${collection?`<div class="vl-source-bar"><div>${icon('car')}<div><h2>Keep exploring.</h2><p>${scoped.length} ${e(collection)} model listings, with original price lists and specifications on every card.</p></div></div>${button('Explore all brands','#brands','secondary','car')}<p class="vl-source-note">Published model prices include VAT, registration and road tax as stated in the linked PDFs. Confirm equipment, final prices and availability with Unicars.</p></div>`:`<div class="vl-source-bar"><div>${icon('document')}<div><h2>Your documents. Ready to keep.</h2><p>${data.totalDocumentCount||data.uniqueDocuments} original PDFs for ${data.models.length} model listings and eHub equipment. ZIP download: ${data.download.megabytes||27} MB.</p></div></div><div class="vl-bundle-action"><button type="button" class="button secondary vl-bundle-download" data-vl-download-all><span data-vl-download-label>Download all PDFs</span>${icon('download')}</button><p id="vlBundleStatus" role="status" aria-live="polite"></p></div><p class="vl-source-note">Published source checked 20 November 2026. Prices shown include VAT, registration and road tax as stated in the PDFs. Model years, equipment and prices may change; confirm the final price and availability with Unicars. This library is not a live stock feed.</p></div>`}`;
 }
 function gallery(m,detail=false){const count=m.images.length;return `<div class="vl-gallery ${detail?'vl-gallery-large':''}" data-vl-gallery="${m.id}" role="region" aria-roledescription="carousel" aria-label="${e(m.brand+' '+m.model)} images" tabindex="${count>1?0:-1}"><div class="vl-gallery-track">${m.images.map((im,i)=>`<figure class="vl-slide"><img src="${e(im.src)}" alt="${e(im.alt)}" class="${im.fit==='cover'?'vl-cover':''}" loading="${detail&&i===0?'eager':'lazy'}" decoding="async" width="1050" height="635"><figcaption>${e(im.caption)}</figcaption></figure>`).join('')}</div>${count>1?`<span class="vl-image-count" aria-live="off">1 / ${count}</span><button type="button" class="vl-gallery-arrow vl-prev" data-vl-step="-1" aria-label="Previous image of ${e(m.model)}" disabled>${icon('back')}</button><button type="button" class="vl-gallery-arrow vl-next" data-vl-step="1" aria-label="Next image of ${e(m.model)}">${icon('arrow')}</button><div class="vl-gallery-dots">${m.images.map((_,i)=>`<button type="button" data-vl-slide="${i}" aria-label="Image ${i+1} of ${e(m.model)}" aria-current="${i===0?'true':'false'}"></button>`).join('')}</div>`:''}</div>`;}
 function card(m){const matched=state.engines.filter(k=>m.powertrains.includes(k)&&k!==m.powertrain);return `<article class="vl-card" aria-labelledby="vl-name-${m.id}">${gallery(m)}<div class="vl-card-body"><p class="vl-brand">${e(m.brand)}</p><h2 id="vl-name-${m.id}">${e(m.model)}</h2><ul class="vl-spec-tags" aria-label="Entry model details"><li class="vl-engine">${e(m.matchingVersion?(core.engineNames[m.matchingVersion.powertrain]||'See specifications'):m.powertrainLabel)}</li>${(m.matchingVersion?.transmission||m.transmission)?`<li>${m.matchingVersion?.transmission?(m.matchingVersion.transmission==='automatic'?'Automatic':'Manual'):m.transmission}</li>`:''}<li>${e(m.matchingVersion?(m.matchingVersion.body==='suv'?'SUV':m.matchingVersion.body[0].toUpperCase()+m.matchingVersion.body.slice(1)):m.body)}</li></ul>${m.matchingVersion?`<p class="vl-match-note">${e(m.matchingVersion.trim)}</p>`:''}<div class="vl-price"><span>Base model from</span><strong>${money(m.price)}</strong></div>${m.matchingVersion&&m.matchingPrice!==m.price?`<p class="vl-matching-price">Matching version from <strong>${money(m.matchingPrice)}</strong></p>`:''}<p class="vl-card-note">Published price · availability to confirm</p>${m.dateNeedsConfirmation?'<p class="vl-date-warning">Source date needs confirmation</p>':''}<div class="vl-card-actions">${button('View vehicle','#range-'+m.id)}${button('Price list',m.document,'secondary','document',`target="_blank" rel="noopener" aria-label="View ${e(m.brand+' '+m.model)} price list PDF (opens in a new tab)"`)}</div><div class="vl-card-document"><span>${e(m.sourceIssued)} price list</span><span>PDF · ${(m.documentBytes/1024/1024).toFixed(1)} MB</span></div></div></article>`;}
 function chips(collection=null){const a=[];if(state.brand!=='all'&&state.brand!==collection)a.push(['brand',state.brand,state.brand]);if(state.query)a.push(['query',state.query,'“'+state.query+'”']);state.engines.forEach(v=>a.push(['engine',v,core.engineNames[v]]));state.bodies.forEach(v=>a.push(['body',v,v]));if(state.budget)a.push(['budget','',`Up to ${money(state.budget)}`]);return a.map(([kind,value,label])=>`<button type="button" class="vl-chip" data-vl-remove="${kind}" data-value="${e(value)}" aria-label="Remove ${e(label)} filter">${e(label)}${icon('close')}</button>`).join('');}
 function update(root,data){const locked=root.dataset.collectionBrand||null,scoped=core.collectionModels(data.models,locked);if(locked)state.brand=locked;collectionStates.set(root.dataset.libraryRoute,{state,limit});const found=core.filterModels(scoped,state);root.querySelector('#vlCount').innerHTML=`<strong>${found.length}</strong> ${found.length===1?'model':'models'}${found.length!==scoped.length?' of '+scoped.length:''}`;root.querySelector('#vlGrid').innerHTML=found.length?found.slice(0,limit).map(card).join(''):`<div class="vl-empty"><span>${icon('search')}</span><h2>No models match just yet.</h2><p>Try a different brand, a higher starting-price budget or fewer filters.</p><button type="button" class="button primary" data-vl-reset>Clear filters ${icon('close')}</button></div>`;root.querySelector('#vlChips').innerHTML=chips(locked);root.querySelectorAll('[data-vl-brand]').forEach(b=>b.setAttribute('aria-pressed',String(b.dataset.vlBrand===state.brand)));root.querySelector('#vlFilterBadge').textContent=core.activeFilterCount(locked?{...state,brand:'all'}:state)||'';const labels={range:'Model range','price-low':'Price: low to high','price-high':'Price: high to low',name:'Brand & model: A–Z'};root.querySelector('#vlSortLabel').textContent=labels[state.sort];root.querySelector('#vlMore').innerHTML=found.length>limit?`<p>Showing ${Math.min(limit,found.length)} of ${found.length} models</p><button type="button" class="button secondary" data-vl-more>Show more models ${icon('car')}</button>`:'';syncFields(root);bindGalleries(root);}
 function syncFields(root){root.querySelectorAll('input[name=engine]').forEach(i=>i.checked=state.engines.includes(i.value));root.querySelectorAll('input[name=body]').forEach(i=>i.checked=state.bodies.includes(i.value));root.querySelectorAll('input[name=budget]').forEach(i=>i.checked=Number(i.value)===state.budget);root.querySelectorAll('input[name=sort]').forEach(i=>i.checked=i.value===state.sort);const search=root.querySelector('#vlSearch');if(search.value!==state.query)search.value=state.query;}
 function bind(root,data){let searchTimer;const change=()=>{if(!root.isConnected)return;limit=24;update(root,data)};root.addEventListener('input',event=>{if(event.target.id==='vlSearch'){state.query=event.target.value;clearTimeout(searchTimer);searchTimer=setTimeout(change,120);}});root.addEventListener('change',event=>{const t=event.target;if(t.name==='engine')state.engines=[...root.querySelectorAll('input[name=engine]:checked')].map(i=>i.value);else if(t.name==='body')state.bodies=[...root.querySelectorAll('input[name=body]:checked')].map(i=>i.value);else if(t.name==='budget')state.budget=Number(t.value);else if(t.name==='sort'){state.sort=t.value;root.querySelector('.vl-sort').open=false;root.querySelector('.vl-sort summary').focus();}else return;clearTimeout(searchTimer);change();});root.addEventListener('submit',event=>{if(event.target.id==='vlFilters')event.preventDefault()});root.addEventListener('click',event=>{const vehicleLink=event.target.closest('a[href^="#range-"]');if(vehicleLink)lastLibraryRoute=root.dataset.libraryRoute||'prices';const b=event.target.closest('button');if(!b)return;if(b.hasAttribute('data-vl-download-all')){downloadBundle(b,data);return;}if(b.hasAttribute('data-vl-brand')){state.brand=b.dataset.vlBrand;change()}else if(b.hasAttribute('data-vl-reset')){state={...core.defaultFilters,engines:[],bodies:[],brand:root.dataset.collectionBrand||'all'};change()}else if(b.hasAttribute('data-vl-remove')){const type=b.dataset.vlRemove,value=b.dataset.value;if(type==='brand')state.brand='all';if(type==='query')state.query='';if(type==='engine')state.engines=state.engines.filter(v=>v!==value);if(type==='body')state.bodies=state.bodies.filter(v=>v!==value);if(type==='budget')state.budget=0;change();root.querySelector('#vlSearch').focus()}else if(b.hasAttribute('data-vl-more')){const old=limit;limit+=24;update(root,data);root.querySelectorAll('.vl-card h2')[old]?.setAttribute('tabindex','-1');root.querySelectorAll('.vl-card h2')[old]?.focus({preventScroll:true})}else if(b.matches('.vl-mobile-filter,.vl-show-results')){const toggle=root.querySelector('.vl-mobile-filter'),open=toggle.getAttribute('aria-expanded')!=='true';toggle.setAttribute('aria-expanded',String(open));root.querySelector('#vlFilterPanel').classList.toggle('is-open',open);if(!open){toggle.focus();toggle.scrollIntoView({block:'nearest'})}}});root.addEventListener('keydown',event=>{if(event.key==='Escape'){const sort=root.querySelector('.vl-sort');if(sort.open){sort.open=false;sort.querySelector('summary').focus()}}});}

 async function downloadBundle(control,data){
  if(control.disabled)return;
  const label=control.querySelector('[data-vl-download-label]'),status=document.getElementById('vlBundleStatus');
  control.disabled=true;control.setAttribute('aria-busy','true');label.textContent='Preparing your PDFs…';status.textContent='Preparing the full document library. Please keep this page open.';
  try{
   const buffers=[];for(let i=0;i<data.download.parts.length;i++){status.textContent=`Preparing download (${i+1} of ${data.download.parts.length})…`;const response=await fetch(data.download.parts[i]);if(!response.ok)throw Error('Download unavailable');buffers.push(await response.arrayBuffer());}
   const blob=new Blob(buffers,{type:'application/zip'});if(blob.size!==data.download.bytes)throw Error('Incomplete download');
   if(globalThis.crypto?.subtle){const hash=await crypto.subtle.digest('SHA-256',await blob.arrayBuffer());const actual=Array.from(new Uint8Array(hash),n=>n.toString(16).padStart(2,'0')).join('');if(actual!==data.download.sha256)throw Error('Download integrity check failed');}
   const url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download=data.download.filename;document.body.append(link);link.click();link.remove();setTimeout(()=>URL.revokeObjectURL(url),60000);status.textContent='Your PDF bundle is ready. Check your downloads.';
  }catch(err){status.textContent='The bundle could not download. Please try again, or open individual PDFs from the model cards.';}
  finally{control.disabled=false;control.removeAttribute('aria-busy');label.textContent='Download all PDFs';}
 }
 document.addEventListener('click',event=>{document.querySelectorAll('.vl-sort[open]').forEach(d=>{if(!d.contains(event.target))d.open=false})});
 function bindGalleries(root){root.querySelectorAll('[data-vl-gallery]').forEach(g=>{if(g.dataset.bound)return;g.dataset.bound='true';const track=g.querySelector('.vl-gallery-track'),slides=[...track.children],n=slides.length;if(n<2)return;const index=()=>Math.max(0,Math.min(n-1,Math.round(track.scrollLeft/track.clientWidth)));const go=i=>track.scrollTo({left:Math.max(0,Math.min(n-1,i))*track.clientWidth,behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'instant':'smooth'});const sync=()=>{let i=index();g.querySelector('.vl-image-count').textContent=`${i+1} / ${n}`;g.querySelector('.vl-prev').disabled=i===0;g.querySelector('.vl-next').disabled=i===n-1;g.querySelectorAll('[data-vl-slide]').forEach((b,j)=>b.setAttribute('aria-current',String(i===j)))};g.addEventListener('click',event=>{const step=event.target.closest('[data-vl-step]'),dot=event.target.closest('[data-vl-slide]');if(step)go(index()+Number(step.dataset.vlStep));if(dot)go(Number(dot.dataset.vlSlide))});g.addEventListener('keydown',event=>{if(event.key==='ArrowRight'||event.key==='ArrowLeft'){event.preventDefault();go(index()+(event.key==='ArrowRight'?1:-1))}});track.addEventListener('scroll',sync,{passive:true});new ResizeObserver(()=>{track.scrollLeft=index()*track.clientWidth;sync()}).observe(track);});}
 async function mountVehicle(id){const root=document.getElementById('rangeVehicle');if(!root)return;try{const data=await load();if(!root.isConnected)return;const m=data.models.find(v=>v.id===id);if(!m){root.querySelector('.vl-wrap').innerHTML=`<div class="vl-empty"><h1>This model couldn’t be found.</h1>${button('Explore the model library','#prices')}</div>`;return}root.querySelector('.vl-wrap').innerHTML=`<div class="vl-detail-back">${button(lastLibraryRoute.startsWith('brand-')?'Back to '+m.brand+' models':'Back to all models','#'+lastLibraryRoute,'secondary','back')}</div><div class="vl-detail-grid"><div>${gallery(m,true)}<div class="vl-detail-image-note">Images illustrate the model; colour, trim and equipment may differ from the starting-price version.</div></div><div class="vl-detail-copy"><p class="vl-eyebrow">${e(m.brand)}</p><h1>${e(m.model)}</h1><ul class="vl-spec-tags"><li class="vl-engine">${e(m.powertrainLabel)}</li>${m.transmission?`<li>${m.transmission}</li>`:''}<li>${m.body}</li></ul><div class="vl-detail-price"><span>Base model from</span><strong>${money(m.price)}</strong><p>Includes VAT, registration & road tax as stated in the source PDF.</p></div><p class="vl-card-note">Published price · availability to confirm</p><div class="vl-detail-actions">${button('View price list & specifications',m.document,'primary','document','target="_blank" rel="noopener"')}${button('Book a test drive','#test-drive?model='+m.id,'secondary','car')}${button('Download PDF',m.document,'secondary','download','download')}</div><div class="vl-detail-engines"><h2>Engines across the range</h2><div class="vl-spec-tags">${m.powertrains.map(k=>`<span>${core.engineNames[k]}</span>`).join('')}</div><p>The starting price above is for the entry model. Other engines and equipment have different prices; see the PDF for the full breakdown.</p></div></div></div>${window.renderModelSourceDetails?window.renderModelSourceDetails(m):''}<div class="vl-document-section"><a class="vl-pdf-preview" href="${e(m.document)}" target="_blank" rel="noopener" aria-label="Open ${e(m.model)} price list PDF"><img src="${e(m.documentPreview)}" alt="First page of the published ${e(m.model)} price list" loading="lazy" width="636" height="900"></a><div><p class="vl-eyebrow">THE ORIGINAL DOCUMENT</p><h2>Every version.<br>Every detail.</h2><p>Explore published prices, technical data and equipment in the original Unicars price list.</p><dl><div><dt>Price list issued</dt><dd>${e(m.sourceIssued)}</dd></div><div><dt>Source checked</dt><dd>20 November 2026</dd></div><div><dt>Document</dt><dd>PDF · ${(m.documentBytes/1024/1024).toFixed(1)} MB</dd></div></dl>${m.dateNeedsConfirmation?'<p class="vl-date-warning">The source PDF is dated July 2027. Confirm this date and the price with Unicars before relying on it.</p>':''}${button('Download price list',m.document,'secondary','download','download')}<p class="vl-source-note">Prices and equipment may change without notice. Photos do not confirm current stock. Contact Unicars for the latest price, equipment and availability.</p></div></div>`;bindGalleries(root);}catch(err){if(root.isConnected)fail(root.querySelector('.vl-wrap'));}}
})();
